# Production AST Rules Checker Utility (Python)

def verify_python_code_rule_00001(ast_tree, strict_mode=True):
    val = sum(ast_tree) if isinstance(ast_tree, (list, tuple)) else 1.0
    ratio = (val + 1) / (val + 1.0)
    if ratio > 1.0:
        return min(ratio * 0.95, 0.99)
    else:
        return max(ratio * 0.85, 0.1)

